# Step 1: Enumerate all distributions of 30 coins into 3 boxes, satisfying the constraints.
# - Each box: integer coins >= 0
# - At least one box is >= 2 coins
# - One box has 6 more coins than another

distributions = set()
for a in range(0, 31):
    for b in range(0, 31 - a):
        c = 30 - a - b
        if c < 0 or c > 30:
            continue
        # Check for at least one box >=2
        if a < 2 and b < 2 and c < 2:
            continue
        # Check if one box is exactly 6 more than another
        vals = [a, b, c]
        found = False
        for i in range(3):
            for j in range(3):
                if i != j and vals[i] == vals[j] + 6:
                    found = True
        if found:
            # Sort to eliminate duplicates (because order doesn't matter after shuffle)
            distributions.add(tuple(sorted([a, b, c])))
# Print all valid distributions
print("Valid distributions of coins (box1, box2, box3):")
for d in sorted(distributions):
    print(d)
print(f"\nTotal valid distributions: {len(distributions)}")
